import { Contract, GlobalState, abimethod, uint64, Txn, Global, Uint64, assert, Account, itxn, gtxn } from '@algorandfoundation/algorand-typescript'

export class JokePayPerCall extends Contract {
  owner = GlobalState<Account>({ key: 'o' })
  totalCalls = GlobalState<uint64>({ key: 'tc' })
  totalEarned = GlobalState<uint64>({ key: 'te' })
  pricePerCall = GlobalState<uint64>({ key: 'p' })

  public createApplication(): void {
    this.owner.value = Txn.sender
    this.totalCalls.value = Uint64(0)
    this.totalEarned.value = Uint64(0)
    this.pricePerCall.value = Uint64(0)
  }

  @abimethod()
  public initialize(price: uint64): void {
    assert(Txn.sender === this.owner.value, 'Only owner can initialize')
    this.pricePerCall.value = price
  }

  @abimethod()
  public record_payment(): void {
    // Verify this is part of a group transaction (Payment + App Call)
    assert(Global.groupSize >= Uint64(2), 'Payment transaction required in group')

    // The payment should be the transaction immediately preceding this app call
    // In a standard x402 flow, the payment is often the first txn (index 0)
    const payment = gtxn.PaymentTxn(Uint64(0))

    // Verify payment details
    assert(payment.receiver.bytes === Global.currentApplicationAddress.bytes, 'Payment must be sent to contract')
    assert(payment.amount >= this.pricePerCall.value, 'Payment amount below price per call')

    // Update state
    this.totalCalls.value = this.totalCalls.value + Uint64(1)
    this.totalEarned.value = this.totalEarned.value + payment.amount
  }

  @abimethod()
  public get_stats(): uint64 {
    const calls: uint64 = this.totalCalls.value
    return calls
  }

  @abimethod()
  public withdraw(): void {
    assert(Txn.sender === this.owner.value, 'Only owner can withdraw')

    // Send all accumulated ALGO to the owner
    // We use closeRemainderTo to empty the account while respecting MBR
    itxn.payment({
      receiver: this.owner.value,
      amount: Uint64(0),
      closeRemainderTo: this.owner.value,
      fee: Uint64(0)
    }).submit()
  }
}

